49	    void expandBounds(const Vec2& point, Vec2& lower, Vec2& upper, bool& valid)
50	    {
51	        if (!valid)
52	        {
53	            lower = point;
54	            upper = point;
55	            valid = true;
56	            return;
57	        }
58	
59	        lower.x = std::min(lower.x, point.x);
60	        lower.y = std::min(lower.y, point.y);
61	        upper.x = std::max(upper.x, point.x);
62	        upper.y = std::max(upper.y, point.y);
63	    }
