272	void PhysicsDebugDraw::drawShape(PhysicsShape* shape)
273	{
274	    if (_drawNode == nullptr || shape == nullptr)
275	    {
276	        return;
277	    }
278	
279	    PhysicsBody* body = shape->getBody();
280	    if (body == nullptr)
281	    {
282	        return;
283	    }
284	
285	    const Color4F fillColor = getShapeColor(shape);
286	    const Color4F outlineColor(fillColor.r, fillColor.g, fillColor.b, 1.0f);
287	    const Color4F hollowColor(fillColor.r, fillColor.g, fillColor.b, 0.0f);
288	    const float angle = PhysicsHelper::cpfloat2float(cpBodyGetAngle(body->getCPBody()));
289	
290	    switch (shape->getType())
291	    {
292	        case PhysicsShape::Type::CIRCLE:
293	        {
294	            for (auto subShape : shape->_cpShapes)
295	            {
296	                const float radius = PhysicsHelper::cpfloat2float(cpCircleShapeGetRadius(subShape));
297	                const Vec2 centre = body->local2World(PhysicsHelper::cpv2point(cpCircleShapeGetOffset(subShape)));
298	                drawCircleShape(centre, radius, angle, fillColor, outlineColor);
299	            }
300	            break;
301	        }
302	        case PhysicsShape::Type::BOX:
303	        case PhysicsShape::Type::POLYGON:
304	        {
305	            for (auto subShape : shape->_cpShapes)
306	            {
307	                const int count = cpPolyShapeGetCount(subShape);
308	                if (count < 2)
309	                {
310	                    continue;
311	                }
312	
313	                std::vector<Vec2> verts(count);
314	                for (int i = 0; i < count; ++i)
315	                {
316	                    verts[i] = body->local2World(PhysicsHelper::cpv2point(cpPolyShapeGetVert(subShape, i)));
317	                }
318	                drawPolygonShape(verts.data(), count, fillColor, outlineColor);
319	            }
320	            break;
321	        }
322	        case PhysicsShape::Type::EDGEBOX:
323	        case PhysicsShape::Type::EDGEPOLYGON:
324	        {
325	            // one segment per edge, the begin points are the polygon loop
326	            const int count = static_cast<int>(shape->_cpShapes.size());
327	            if (count < 3)
328	            {
329	                break;
330	            }
331	
332	            std::vector<Vec2> verts(count);
333	            for (int i = 0; i < count; ++i)
334	            {
335	                verts[i] = body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetA(shape->_cpShapes[i])));
336	            }
337	            drawPolygonShape(verts.data(), count, hollowColor, outlineColor);
338	            break;
339	        }
340	        case PhysicsShape::Type::EDGESEGMENT:
341	        case PhysicsShape::Type::EDGECHAIN:
342	        {
343	            for (auto subShape : shape->_cpShapes)
344	            {
345	                const Vec2 a = body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetA(subShape)));
346	                const Vec2 b = body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetB(subShape)));
347	                drawSegmentShape(a, b, _config.lineWidth, outlineColor);
348	            }
349	            break;
350	        }
351	        case PhysicsShape::Type::UNKNOWN:
352	        default:
353	            break;
354	    }
355	}
