497	void PhysicsDebugDraw::drawVelocityVector(const Vec2& pos, const Vec2& vel, const Color4F& color)
498	{
499	    if (_drawNode == nullptr)
500	    {
501	        return;
502	    }
503	
504	    const Vec2 delta = vel * kVelocityScale;
505	    if (delta.getLength() < kMinDrawLength)
506	    {
507	        return;
508	    }
509	
510	    const Vec2 tip = pos + delta;
511	    const Vec2 dir = delta.getNormalized();
512	    const Vec2 back = tip - dir * kArrowHeadSize;
513	    const Vec2 side = dir.getPerp() * (kArrowHeadSize * 0.5f);
514	
515	    _drawNode->drawLine(pos, tip, color);
516	    _drawNode->drawLine(tip, back + side, color);
517	    _drawNode->drawLine(tip, back - side, color);
518	}
